hmmsearch -o secretome/oxidative_proteins/hmmsearch_output/PF00070_hmmsearch.txt --noali --cpu 4 -E 0.01 secretome/oxidative_proteins/input_data/PF00070.hmm secretome/oxidative_proteins/input_data/combined_proteins.fasta # Run HMMSEARH with one of the HMMs
